// Get the text from the CORRECT part of the AI's output (index 1)
const text = $input.item.json.content.parts[1].text;

// This helper function now looks for a label and captures the rest of that line.
const getValue = (label) => {
  // The regex is updated for newline-separated data.
  // It captures any character that is NOT a newline: ([^\\n]*)
  const regex = new RegExp(label + ':\\s*([^\\n]*)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : null;
};

// Use the helper function to get all your values safely
const description = getValue('Meal Description') || 'Unknown';
const calories = parseInt(getValue('Total Calories')) || 0;
const proteins = parseInt(getValue('Total Proteins')) || 0;
const carbs = parseInt(getValue('Total Carbs')) || 0;
const fat = parseInt(getValue('Total Fat')) || 0;

// Build the final output object
const outputItem = {
  json: {
    // Keep the original input data
    ...$input.item.json,
    // Add the new, correctly parsed data
    updatedNutrition: {
      mealDescription: description,
      calories: calories,
      proteins: proteins,
      carbs: carbs,
      fat: fat
    }
  }
};

return outputItem;
